edits.before:
match /payment_reconciliation_settings/{id} {
  function reconciliationProvider(data) {
    return data.keys().hasOnly(['orderPrefixes','referencePrefixes','timeToleranceMinutes'])
      && data.orderPrefixes is list && data.orderPrefixes.size() <= 10 && data.referencePrefixes is list && data.referencePrefixes.size() <= 10
      && data.timeToleranceMinutes is int && data.timeToleranceMinutes >= 0 && data.timeToleranceMinutes <= 120;
  }

  function reconciliationSettings(data,before) {
    return id == 'main' && protectedHROwner() && data.keys().hasOnly(['schemaVersion','revision','branchAliases','providers','updatedAt','updatedByUid','updatedByEmail'])
      && data.schemaVersion == 1 && data.revision is int && data.revision == before.get('revision',0) + 1
      && data.branchAliases is list && data.branchAliases.size() <= 60 && data.providers is map && data.providers.keys().hasOnly(['GCash','Grab','Foodpanda'])
      && reconciliationProvider(data.providers.GCash) && reconciliationProvider(data.providers.Grab) && reconciliationProvider(data.providers.Foodpanda)
      && data.updatedAt == reqTime() && data.updatedByUid == reqUid() && data.updatedByEmail == reqEmail();
  }
  allow get: if id == 'main' && protectedHROwner();
  allow create, update: if reconciliationSettings(newData(),resource == null ? {} : oldData());
  allow list, delete: if false;
}
match /payment_reconciliation_imports/{id} {
  function reconciliationImportHash(value) { return value is string && value.matches('^[a-f0-9]{64}$'); }

  allow read: if protectedHROwner();
  allow create: if protectedHROwner() && reconciliationImportHash(id) && newData().keys().hasOnly(['schemaVersion','fileSha256','rowCount','createdAt','createdByUid','createdByEmail'])
    && newData().schemaVersion == 1 && newData().fileSha256 == id && newData().rowCount is int && newData().rowCount > 0 && newData().rowCount <= 5000
    && newData().createdAt == reqTime() && newData().createdByUid == reqUid() && newData().createdByEmail == reqEmail();
  allow update, delete: if false;
}
match /payment_reconciliation_receipts/{id} {
  function reconciliationReceiptHash(value) { return value is string && value.matches('^[a-f0-9]{64}$'); }

  function reconciliationReceipt(data,id) {
    let before = transactionBefore(id);
    let after = transactionAfter(id);
    let settings = readData('payment_reconciliation_settings','main');
    let imported = nextData('payment_reconciliation_imports',data.fileSha256);
    let day = data.day.split('-');
    let midnight = timestamp.date(int(day[0]),int(day[1]),int(day[2])) - duration.value(8,'h');
    return protectedHROwner() && protectedHRId(id) && data.transactionId == id && reconciliationReceiptHash(data.claimId) && reconciliationReceiptHash(data.fileSha256)
      && data.keys().hasOnly(['schemaVersion','claimId','transactionId','fileSha256','provider','branch','day','grossCents','statementAt','sourceAt','sourceFingerprint','settingsRevision','verifiedAt','verifiedByUid','verifiedByEmail'])
      && data.schemaVersion == 1 && data.provider in ['GCash','Grab','Foodpanda'] && reconciliationReceiptHash(data.sourceFingerprint)
      && data.settingsRevision == settings.revision && imported.schemaVersion == 1 && imported.fileSha256 == data.fileSha256
      && !exists(/databases/$(database)/documents/payment_reconciliation_rows/$(data.claimId)) && nextData('payment_reconciliation_rows',data.claimId) == data
      && data.verifiedAt == reqTime() && data.verifiedByUid == reqUid() && data.verifiedByEmail == reqEmail()
      && before.get('paymentVerified',false) != true && before.branch == data.branch && before.timestamp == data.sourceAt
      && before.netTotal is number && before.netTotal > 0 && data.grossCents is int && data.grossCents == int(before.netTotal * 100 + 0.5)
      && before.netTotal == data.grossCents / 100.0 && (data.provider == 'Foodpanda' ? before.paymentMethod.trim().lower() in ['foodpanda','food panda','panda'] : before.paymentMethod.trim().lower() == data.provider.lower())
      && before.get('status','').trim().lower() in ['paid','complete','completed','settled','received']
      && (before.get('paymentStatus',null) == null || before.paymentStatus.trim().lower() in ['paid','complete','completed','settled','received']) && before.get('isPendingSync',false) != true
      && before.get('cancelledFoodSourceId','') == '' && before.get('preparedCancellation',null) == null
      && before.get('cancelled',false) != true && before.get('canceled',false) != true && before.get('refunded',false) != true && before.get('refundAmount',0) <= 0
      && (before.get('splitDetails',null) == null || before.splitDetails is list && before.splitDetails.size() == 0)
      && (!exists(/databases/$(database)/documents/online_order_incidents/$('online-refund-' + id))
        || readData('online_order_incidents','online-refund-' + id).status == 'Dismissed')
      && data.statementAt is timestamp && data.sourceAt is timestamp && protectedHRDate(data.day)
      && data.sourceAt >= midnight && data.sourceAt < midnight + duration.value(1,'d') && data.statementAt >= midnight && data.statementAt < midnight + duration.value(1,'d')
      && data.statementAt >= data.sourceAt - duration.value(settings.providers[data.provider].timeToleranceMinutes,'m')
      && data.statementAt <= data.sourceAt + duration.value(settings.providers[data.provider].timeToleranceMinutes,'m')
      && after.diff(before).affectedKeys().hasOnly(['paymentVerified','verifiedBy','verifiedAt','paymentReconciliationVersion','paymentReconciliationId','paymentReconciliationFile'])
      && after.paymentVerified == true && after.verifiedBy == reqEmail() && after.verifiedAt == reqTime()
      && after.paymentReconciliationVersion == 1 && after.paymentReconciliationId == data.claimId && after.paymentReconciliationFile == data.fileSha256;
  }

  allow read: if protectedHROwner();
  allow create: if reconciliationReceipt(newData(),id);
  allow update, delete: if false;
}
match /payment_reconciliation_rows/{id} {
  function reconciliationRowHash(value) { return value is string && value.matches('^[a-f0-9]{64}$'); }

  allow read: if protectedHROwner();
  // A fresh reciprocal receipt invokes its full validation in this request.
  allow create: if protectedHROwner() && reconciliationRowHash(id) && newData().claimId == id
    && !exists(/databases/$(database)/documents/payment_reconciliation_receipts/$(newData().transactionId))
    && nextData('payment_reconciliation_receipts',newData().transactionId) == newData();
  allow update, delete: if false;
}

edits.after:
match /payment_reconciliation_settings/{id} {
  allow get: if id == 'main' && protectedHROwner();
  allow list, create, update, delete: if false; // Trusted reconciliation service only.
}
match /payment_reconciliation_imports/{id} {
  allow read: if protectedHROwner();
  allow create, update, delete: if false; // Trusted reconciliation service only.
}
match /payment_reconciliation_receipts/{id} {
  allow read: if protectedHROwner();
  allow create, update, delete: if false; // Trusted reconciliation service only.
}
match /payment_reconciliation_rows/{id} {
  allow read: if protectedHROwner();
  allow create, update, delete: if false; // Trusted reconciliation service only.
}

edits.before:
function docVaultReview(staffId, kind, before, after) {
  let audit = getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/reviews/$(after.reviewId)).data;
  return docVaultHQ(before.branch) && docVaultKind(kind)
    && before.staffId == staffId && before.group == kind
    && after.diff(before).affectedKeys().hasOnly(['status', 'reviewId', 'reviewNote',
      'reviewedByUid', 'reviewedAt', 'updatedAt', 'version'])
    && after.status in ['approved', 'rejected'] && docVaultId(after.reviewId)
    && after.reviewNote is string && after.reviewNote.size() <= 300
    && (after.status != 'rejected' || after.reviewNote.size() >= 3)
    && after.reviewedByUid == reqUid() && after.reviewedAt == reqTime()
    && after.updatedAt == reqTime() && after.version == before.version + 1
    && audit.staffId == staffId && audit.branch == before.branch && audit.group == kind
    && audit.uploadId == before.uploadId && audit.recordVersion == after.version
    && audit.status == after.status && audit.note == after.reviewNote
    && audit.actorUid == reqUid() && audit.recordedAt == reqTime();
}

function docVaultFileCreate(data) {
  return docVaultUpload(staffId, kind, data)
    && data.version == 1
    && getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/versions/$(data.uploadId)).data == data;
}

function docVaultFileUpdate(data,before) {
  return (docVaultUpload(staffId, kind, data)
      && data.version == before.version + 1 && data.uploadId != before.uploadId
      && getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/versions/$(data.uploadId)).data == data)
    || (docVaultReview(staffId, kind, before, data)
      && getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/versions/$(before.uploadId)).data == data);
}

function docVaultVersionCreate(data) {
  return docVaultUpload(staffId, data.group, data)
    && uploadId == data.uploadId
    && getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/files/$(data.group)).data == data;
}

function docVaultVersionUpdate(data,before) {
  return docVaultReview(staffId, before.group, before, data)
    && uploadId == before.uploadId
    && getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/files/$(before.group)).data == data;
}

function docVaultAuditCreate(data) {
  let eligible = docVaultId(reviewId)
    && data.keys().hasOnly(['staffId', 'branch', 'recordVersion', 'group', 'uploadId', 'status', 'note', 'actorUid', 'recordedAt']) && data.size() == 9
    && data.staffId == staffId && docVaultHQ(data.branch)
    && docVaultKind(data.group) && docVaultId(data.uploadId)
    && data.status in ['approved', 'rejected']
    && data.note is string && data.note.size() <= 300
    && data.actorUid == reqUid() && data.recordedAt == reqTime();
  let saved = eligible ? getAfter(/databases/$(database)/documents/staff_private_documents/$(staffId)/files/$(data.group)).data : {};
  return eligible && saved.reviewId == reviewId
    && saved.version == data.recordVersion
    && saved.branch == data.branch
    && saved.uploadId == data.uploadId;
}
